def handle(args, state, ds):
    rep = ds.sync_status()
    if rep.get('drift') is False:
        return {'status': 'synced', 'detail': 'All linked accounts are up to date.'}
    return {'status': 'syncing', 'detail': rep.get('detail', 'Account data is being synchronized.')}

def handle(args, state, ds):
    rep = ds.consistency_report()
    if rep.get('pending', 0) == 0:
        return {'status': 'complete', 'remaining': 0}
    return {'status': 'remaining', 'remaining': rep.get('pending', 0), 'detail': 'Gmail reconciliation is still processing messages.'}

